// PHASE 1 - Normalise: QCM notes + form submissions -> one candidate object
// D1: the meeting and the form cover each other's blind spots, but once
// ingested they must score on equal footing, so both collapse to one shape
// here and nothing downstream knows or cares which source a report came from.
//
// SKETCH: raw inputs are stubbed. In the real build this is two tool calls -
// the QCM minutes doc, and the form's stored submissions since last run.

const RAW = {
  qcm: [
    { role: 'compliance-analyst', person: 'p1', reportedAt: '2026-08-11',
      problem: 'Manual SOC2 evidence collation',
      description: 'Screenshots copied by hand into the evidence folder weekly.',
      hoursPerWeek: 3, affected: 4, stress: 4 },
    { role: 'compliance-analyst', person: 'p2', reportedAt: '2026-08-11',
      problem: 'Manual SOC2 evidence collation',
      description: 'Same collation work, plus chasing people for missing artefacts.',
      hoursPerWeek: 4, affected: 5, stress: 4 }
  ],
  form: [
    { role: 'people-ops', person: 'p9', reportedAt: '2026-08-09',
      problem: 'Onboarding checklist tracked by hand',
      description: 'Spreadsheet drifts out of sync; I re-check every new joiner manually, ~5h/wk.',
      hoursPerWeek: 5, affected: 5, stress: 4 }
  ]
};

// Role-pool sizes - D2 normalises by role, never by company headcount:
// 4 of 4 compliance people drowning beats 15 of 200 mildly annoyed.
const ROLE_POOL = { 'compliance-analyst': 4, 'people-ops': 6 };

// OPEN (pipeline design): clustering different phrasings of the SAME problem
// is itself a judgment task and probably an LLM step, not a string key.
// Stubbed here as exact-title grouping so the sketch stays readable.
const byProblem = {};
for (const [source, rows] of Object.entries(RAW)) {
  for (const r of rows) {
    const key = r.role + '::' + r.problem;
    byProblem[key] = byProblem[key] || {
      id: key, title: r.problem, role: r.role,
      rolePool: { role: r.role, size: ROLE_POOL[r.role] ?? null },
      reports: []
    };
    byProblem[key].reports.push({
      source, person: r.person, reportedAt: r.reportedAt,
      hoursPerWeek: r.hoursPerWeek, affected: r.affected,
      stress: r.stress, description: r.description
    });
  }
}

return Object.values(byProblem).map(c => ({ json: { candidate: {
  ...c,
  stage: 'normalised',
  log: [{ phase: 'P1', action: 'normalised', reports: c.reports.length, at: new Date().toISOString() }]
}}}));

// PHASE 2a - Threshold: 25% of the role-pool, time-decayed
// D2: the fraction and the window matter equally. 25% inside a quarter is a
// live problem; 25% accumulated over three years is background noise. So each
// report's weight halves every HALF_LIFE_DAYS instead of counting forever.
// D3: below-threshold does NOT mean discarded - a lone well-evidenced report
// still reaches a human. A rigid threshold must never SILENTLY kill an idea.

const THRESHOLD = 0.25;
const HALF_LIFE_DAYS = 90;            // one quarter
const CONVICTION_HOURS = 4;           // hours/week that count as 'real numbers'
const CONVICTION_DESC_CHARS = 120;    // a concrete description, not a one-liner

const now = Date.now();
const out = [];

for (const item of $input.all()) {
  const c = item.json.candidate;
  const pool = c.rolePool.size;

  if (!pool) {
    // Nothing is silently dropped - unknown pool size is an escalation,
    // not a default-to-zero.
    c.routing = { route: 'needs_context', reason: 'role-pool size unknown' };
    out.push({ json: { candidate: c } });
    continue;
  }

  const weighted = c.reports.reduce((sum, r) => {
    const ageDays = (now - new Date(r.reportedAt).getTime()) / 86400000;
    return sum + Math.pow(0.5, ageDays / HALF_LIFE_DAYS);
  }, 0);

  const decayedFraction = weighted / pool;
  const distinctPeople = new Set(c.reports.map(r => r.person)).size;

  // D3 route 2: below threshold, but a form submission carries real numbers.
  const highConviction = c.reports.some(r =>
    r.source === 'form' &&
    (r.hoursPerWeek ?? 0) >= CONVICTION_HOURS &&
    (r.description || '').length >= CONVICTION_DESC_CHARS
  );

  c.threshold = {
    decayedFraction: Number(decayedFraction.toFixed(3)),
    thresholdUsed: THRESHOLD,
    halfLifeDays: HALF_LIFE_DAYS,
    distinctPeople,
    rolePoolSize: pool
  };

  c.routing = decayedFraction >= THRESHOLD
    ? { route: 'high_signal', reason: 'met 25% of role-pool in-window' }
    : highConviction
      ? { route: 'low_signal_high_conviction', reason: 'below threshold but evidenced hours + concrete description' }
      : { route: 'parked', reason: 'below threshold, no hard evidence - carried, not deleted' };

  c.stage = 'thresholded';
  c.log.push({ phase: 'P2a', action: 'thresholded', route: c.routing.route, fraction: c.threshold.decayedFraction });
  out.push({ json: { candidate: c } });
}

return out;

// PHASE 2c - Fold LLM scores back into candidate state + validate
// STRUCTURAL POINT worth keeping: the LLM node REPLACES the item payload, so
// the candidate would be lost here if it were not explicitly re-merged. This
// is exactly the 'how does state carry across agents' question in the brief -
// state is re-attached at every boundary, never assumed to survive.

const out = [];
for (let i = 0; i < $input.all().length; i++) {
  const scored = $input.all()[i].json;                       // LLM output
  const c = $('PHASE 2a - Threshold: 25% Role-Pool + Time Decay').all()[i].json.candidate;

  const required = ['impactScore', 'sentimentScore', 'confidence', 'unresolvedAssumptions'];
  const missing = required.filter(k => !(k in scored));

  if (missing.length) {
    // Retry-once-then-escalate belongs here. Never pass a malformed artifact
    // downstream, and never drop it silently.
    c.qc = { status: 'schema_failed', missing, action: 'retry once, then escalate to human' };
    c.routing = { route: 'needs_context', reason: 'scorer returned malformed output' };
  } else {
    c.scores = scored;
    c.qc = { status: 'ok' };
    // D2 limitation, stated deliberately: self-reported severity is noisy and
    // gameable, so sentiment is cross-checked, never a headline number.
    c.scores.sentimentCaveat = 'self-reported, gameable; weak signal cross-checked against hours lost + recurrence';
  }

  c.stage = 'scored';
  c.log.push({ phase: 'P2c', action: 'scores_merged', qc: c.qc.status });
  out.push({ json: { candidate: c } });
}
return out;

// PHASE 2d - Rank the weekly batch into ONE reviewable shortlist
// D1/D5: the whole point of a weekly batch over continuous discovery is that
// it produces a reviewable UNIT OF WORK. The team lead sees one ranked list,
// not thirty interruptions.
// Two scores are carried side by side and deliberately NOT collapsed into a
// single number (D2) - the human sees value-of-fixing and distress separately.

const ranked = $input.all()
  .map(i => i.json.candidate)
  .sort((a, b) => (b.scores?.impactScore ?? 0) - (a.scores?.impactScore ?? 0));

ranked.forEach((c, idx) => {
  c.shortlistRank = idx + 1;
  c.log.push({ phase: 'P2d', action: 'ranked', rank: idx + 1 });
});

return ranked.map(c => ({ json: { candidate: c } }));

// GATE 1 - record the team lead's decision into the append-only log
// D4 Gate 1 asks 'is this worth our time?' and the action is: pick from the
// ranked shortlist, or reject. Body arrives on the Wait node's resume URL.

const c = $json.candidate ?? $('PHASE 2d - Rank Shortlist for Gate 1').first().json.candidate;
const decision = $json.body ?? { approved: true, reviewer: 'ai-impl-lead', reason: 'sketch default' };

c.gate1 = {
  reviewer: 'AI implementation team lead',
  question: 'Is this worth our time?',
  approved: decision.approved !== false,
  reason: decision.reason ?? null,
  decidedAt: new Date().toISOString()
};
c.stage = c.gate1.approved ? 'gate1_approved' : 'gate1_rejected';
c.log.push({ phase: 'G1', action: c.stage, reviewer: c.gate1.reviewer });

return [{ json: { candidate: c } }];

// PHASE 4b - Fold the drafted PRD back into candidate state + self-critique
// Same state re-attachment as Phase 2c. The self-critique pass runs BEFORE the
// human sees it (open item B): the agent grades its own PRD against a checklist
// so obvious gaps never reach Gate 2 and waste the problem owner's attention.

const prd = $json;
const c = $('GATE 1 - Record Team Lead Decision').first().json.candidate;

const checklist = ['problem', 'users', 'scope', 'requirements', 'successCriteria'];
const gaps = checklist.filter(k => !prd[k] || (Array.isArray(prd[k]) && !prd[k].length));

c.prd = prd;
c.prdSelfCritique = {
  gaps,
  passed: gaps.length === 0,
  // Low confidence routes to the human WITH the specific question attached,
  // rather than the agent guessing (open item C).
  escalationQuestion: gaps.length ? `PRD is missing: ${gaps.join(', ')} - ask the reporter directly.` : null
};
c.stage = 'prd_drafted';
c.log.push({ phase: 'P4b', action: 'prd_drafted', selfCritiquePassed: c.prdSelfCritique.passed });

return [{ json: { candidate: c } }];

// GATE 2 - apply the problem owner's edits
// D4: the reviewer here is the PERSON WHO RAISED IT, not the team lead - only
// they know whether the PRD describes their actual pain. The action is edit
// and approve, not reject: by this point the problem is already agreed to be
// worth solving (that was Gate 1's question), so the only open question is
// whether it has been understood correctly.

const c = $('PHASE 4b - Merge PRD into State + Self-Critique').first().json.candidate;
const edits = $json.body?.prdEdits ?? {};

c.prd = { ...c.prd, ...edits };
c.gate2 = {
  reviewer: 'the person who raised the problem',
  question: 'Did the system understand the problem correctly?',
  editedFields: Object.keys(edits),
  approvedAt: new Date().toISOString()
};
c.stage = 'prd_approved';
c.log.push({ phase: 'G2', action: 'prd_approved', editedFields: c.gate2.editedFields });

return [{ json: { candidate: c } }];
